      if (finished) {
          revert AlreadyFinished();
      }
      require(block.timestamp > endTime);
      finished = true;

      address winner;
      uint256 maxBid;
      address[] memory allBidders = _getAllBidders();
      for (uint256 i = 0; i < allBidders.length; i++) {
          if (bids[allBidders[i]] > maxBid) {
              maxBid = bids[allBidders[i]];
              winner = allBidders[i];
          }
      }

      if (winner != address(0)) {
          coll.transferFrom(address(this), winner, auctionedToken.tokenId);
      }

      return winner;
  }

